import * as React from "react";

export type SpeakerGrilleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SpeakerGrilleIcon({ size = 20, ...props }: SpeakerGrilleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="3.5" width="12" height="17" rx="2" /><path d="M9.5 7h.5M14 7h.5M9.5 11h.5M14 11h.5M9.5 15h.5M14 15h.5" />
    </svg>
  );
}
